import { z } from 'zod'
import { ERRORS, LOG_LEVELS } from '@/shared/constants'
import type { LogLevel } from '@/shared/constants'
import { AppEnv, EmailProviderName, PasswordBreachCheck, SmsProviderName } from '@/shared/types'
import type { EnvConfig } from './env.type'

const logLevel = Object.keys(LOG_LEVELS) as LogLevel[]

// An empty value (`KEY=""` in .env.example) means "not set".
const optionalSecret = z
  .union([z.literal('').transform(() => undefined), z.string().trim().min(1)])
  .optional()

export const envSchema: z.ZodType<EnvConfig> = z
  .object({
    PORT: z.coerce.number().int().positive().max(65535),
    NODE_ENV: z.enum([AppEnv.DEVELOPMENT, AppEnv.PRODUCTION]),
    BASE_URL: z.string(),
    CORS_ORIGINS: z
      .string()
      .optional()
      .transform((value) =>
        (value ?? '')
          .split(',')
          .map((origin) => origin.trim())
          .filter(Boolean)
      ),
    LOG_LEVEL_CONSOLE: z.enum(logLevel),
    LOG_LEVEL_FILE: z.enum(logLevel),
    LOG_LEVEL_ERROR_FILE: z.enum(logLevel),
    LOG_SILENT: z.stringbool().default(false),
    SHUTDOWN_TIMEOUT_MS: z.coerce.number().int().positive().default(10_000),
    EMAIL_PROVIDER: z.enum(EmailProviderName).default(EmailProviderName.CONSOLE),
    EMAIL_FROM: z.string().trim().min(1).default('Tang Pai Nai <no-reply@localhost>'),
    // An empty value (`SMTP_URL=""` in .env.example) means "not set".
    SMTP_URL: z
      .union([z.literal('').transform(() => undefined), z.url({ protocol: /^smtps?$/ })])
      .optional(),
    SMS_PROVIDER: z.enum(SmsProviderName).default(SmsProviderName.CONSOLE),
    // `file:./data/local.db` (dev), `:memory:` (tests) or `libsql://…turso.io` (prod, + auth token).
    DATABASE_URL: z
      .string()
      .trim()
      .regex(/^(file:|libsql:\/\/|https?:\/\/|:memory:$)/, ERRORS.invalidField('DATABASE_URL'))
      .default('file:./data/local.db'),
    DATABASE_AUTH_TOKEN: z
      .union([z.literal('').transform(() => undefined), z.string().trim().min(1)])
      .optional(),
    // The web app's origin: builds magic links and is the only `Origin` cookie routes accept.
    WEB_ORIGIN: z
      .url({ protocol: /^https?$/ })
      .default('http://localhost:4200')
      .transform((value) => new URL(value).origin),
    // Proxies in front of the API (ng serve's dev proxy, the Vercel rewrite), so `req.ip` is the
    // client's address for rate limits.
    TRUST_PROXY_HOPS: z.coerce.number().int().min(0).max(5).default(1),
    // Random secrets generated by `npm run setup-env`, at least 32 characters.
    JWT_SECRET: z.string().min(32, ERRORS.minLength('JWT_SECRET', 32)),
    OTP_PEPPER: z.string().min(32, ERRORS.minLength('OTP_PEPPER', 32)),
    SIGNUP_ENABLED: z.stringbool().default(true),
    EMAIL_DAILY_LIMIT: z.coerce.number().int().positive().max(100_000).default(100),
    // Breach check of new passwords (auth rule 11). The URL can point at a local stand-in.
    PASSWORD_BREACH_CHECK: z.enum(PasswordBreachCheck).default(PasswordBreachCheck.HIBP),
    HIBP_API_URL: z
      .url({ protocol: /^https?$/ })
      .default('https://api.pwnedpasswords.com')
      .transform((value) => value.replace(/\/+$/, '')),
    // Google sign-in (auth rule 14) is off unless both are set. The issuer can point at the
    // local stand-in (`npm run dev:oidc`).
    GOOGLE_CLIENT_ID: optionalSecret,
    GOOGLE_CLIENT_SECRET: optionalSecret,
    GOOGLE_ISSUER: z
      .url({ protocol: /^https?$/ })
      .default('https://accounts.google.com')
      .transform((value) => value.replace(/\/+$/, '')),
  })
  .superRefine((env, ctx) => {
    if (env.EMAIL_PROVIDER === EmailProviderName.SMTP && !env.SMTP_URL) {
      ctx.addIssue({
        code: 'custom',
        path: ['SMTP_URL'],
        message: ERRORS.requiredField('SMTP_URL'),
      })
    }
    if (Boolean(env.GOOGLE_CLIENT_ID) !== Boolean(env.GOOGLE_CLIENT_SECRET)) {
      const missing = env.GOOGLE_CLIENT_ID ? 'GOOGLE_CLIENT_SECRET' : 'GOOGLE_CLIENT_ID'
      ctx.addIssue({ code: 'custom', path: [missing], message: ERRORS.requiredField(missing) })
    }
    // Console providers print OTPs to stdout: dev only.
    if (env.NODE_ENV === AppEnv.PRODUCTION) {
      if (env.EMAIL_PROVIDER === EmailProviderName.CONSOLE) {
        ctx.addIssue({
          code: 'custom',
          path: ['EMAIL_PROVIDER'],
          message: ERRORS.devOnly('console'),
        })
      }
      if (env.SMS_PROVIDER === SmsProviderName.CONSOLE) {
        ctx.addIssue({ code: 'custom', path: ['SMS_PROVIDER'], message: ERRORS.devOnly('console') })
      }
      // A plain-http issuer is only the local stand-in.
      if (!env.GOOGLE_ISSUER.startsWith('https://')) {
        ctx.addIssue({
          code: 'custom',
          path: ['GOOGLE_ISSUER'],
          message: ERRORS.devOnly('http issuer'),
        })
      }
    }
  })
